def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    objs = objects(g, bg=bg)
    H, W = g.shape
    from collections import defaultdict
    bycol = defaultdict(list)
    for o in objs:
        bycol[o["colour"]].append(o)
    for col, lst in bycol.items():
        if len(lst) != 2:
            continue
        # piece = leftmost object; socket = the other (anchored at right)
        lst = sorted(lst, key=lambda o: (o["box"][1], -o["box"][3]))
        piece, sock = lst[0], lst[1]
        pc = piece["cells"]
        sc = set(sock["cells"])
        done = False
        for dy in range(-H, H):
            for dx in range(-W, W):
                if dy == 0 and dx == 0:
                    continue
                new = [(y + dy, x + dx) for y, x in pc]
                if any(not (0 <= y < H and 0 <= x < W) for y, x in new):
                    continue
                if any((y, x) in sc for y, x in new):
                    continue
                if any(g[y, x] != bg and (y, x) not in set(pc) for y, x in new):
                    continue
                union = sc | set(new)
                y0, x0, y1, x1 = bbox(list(union))
                if len(union) != (y1 - y0 + 1) * (x1 - x0 + 1):
                    continue
                for y, x in pc:
                    out[y, x] = bg
                emit(out.copy(), f"Lift the loose colour-{col} piece (the leftmost one) out of its old position.")
                for y, x in new:
                    out[y, x] = col
                emit(out.copy(), f"Slide the piece by ({dy},{dx}) into the socket's notch, completing a solid rectangle.")
                done = True
                break
            if done:
                break
    emit(out.copy(), "Final grid: every loose piece is plugged into its matching socket.")
    return out
